function validate([robot, factory]) {
  if (!Array.isArray(robot) || robot.length < 1 || robot.length > 100) return 'robot needs 1 to 100 positions.';
  if (!Array.isArray(factory) || factory.length < 1 || factory.length > 100) return 'factory needs 1 to 100 entries.';
  if (factory.some(f => !Array.isArray(f) || f.length !== 2)) return 'Each factory is [position, limit].';
  const inRange = v => Number.isInteger(v) && v >= -1e9 && v <= 1e9;
  if (!robot.every(inRange) || !factory.every(f => inRange(f[0]))) return 'Positions are whole numbers between -10^9 and 10^9.';
  if (factory.some(f => !Number.isInteger(f[1]) || f[1] < 0 || f[1] > robot.length)) return 'Each limit is between 0 and robot.length.';
  if (new Set(robot).size !== robot.length) return 'Robot positions must be distinct.';
  if (new Set(factory.map(f => f[0])).size !== factory.length) return 'Factory positions must be distinct.';
  if (factory.reduce((s, f) => s + f[1], 0) < robot.length) return 'The limits must add up to at least the number of robots.';
  return null;
}

