function minimumTotalDistance(robot, factory) {
  robot.sort((a, b) => a - b);
  factory.sort((a, b) => a[0] - b[0]);
  const n = robot.length;
  const m = factory.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(Infinity));
  dp[0][0] = 0;

  for (let j = 1; j <= m; j++) {
    const [position, limit] = factory[j - 1];
    for (let i = 0; i <= n; i++) {
      dp[j][i] = dp[j - 1][i];
      let cost = 0;
      for (let k = 1; k <= Math.min(limit, i); k++) {
        cost += Math.abs(robot[i - k] - position);
        dp[j][i] = Math.min(dp[j][i], dp[j - 1][i - k] + cost);
      }
    }
  }
  return dp[m][n];
}

