function minimumTotalDistance(robot, factory) {
  // Try every way to send each robot to a factory with room left.
  const room = factory.map(f => f[1]);
  let best = Infinity;
  const place = (r, total) => {
    if (total >= best) return;
    if (r === robot.length) { best = total; return; }
    for (let f = 0; f < factory.length; f++) {
      if (room[f] === 0) continue;
      room[f]--;
      place(r + 1, total + Math.abs(robot[r] - factory[f][0]));
      room[f]++;
    }
  };
  place(0, 0);
  return best;
}

