function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 6);
  const m = large ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 4);
  const span = large ? 1e9 : (rand() < 0.15 ? 1e9 : 15);
  const distinct = (count) => {
    const seen = new Set();
    while (seen.size < count) seen.add(Math.floor(rand() * (2 * span + 1)) - span);
    return [...seen];
  };
  const robot = distinct(n);
  const positions = distinct(m);
  const cap = large ? 3 : n;
  const factory = positions.map(p => [p, Math.floor(rand() * (cap + 1))]);
  // Make sure every robot can be fixed by raising random limits.
  let total = factory.reduce((s, f) => s + f[1], 0);
  while (total < n) {
    const f = factory[Math.floor(rand() * m)];
    if (f[1] < n) { f[1]++; total++; }
  }
  return [robot, factory];
}
